Tests that will be run with `zig test`:
```zig
const std = @import("std");
const testing = std.testing;

const rectangles = @import("rectangles.zig");

test "no rows" {
    const strings = [_][]const u8{};
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(0, count);
}

test "no columns" {
    const strings = [_][]const u8{
        "", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(0, count);
}

test "no rectangles" {
    const strings = [_][]const u8{
        " ", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(0, count);
}

test "one rectangle" {
    const strings = [_][]const u8{
        "+-+", //
        "| |", //
        "+-+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(1, count);
}

test "two rectangles without shared parts" {
    const strings = [_][]const u8{
        "  +-+", //
        "  | |", //
        "+-+-+", //
        "| |  ", //
        "+-+  ", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(2, count);
}

test "five rectangles with shared parts" {
    const strings = [_][]const u8{
        "  +-+", //
        "  | |", //
        "+-+-+", //
        "| | |", //
        "+-+-+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(5, count);
}

test "rectangle of height 1 is counted" {
    const strings = [_][]const u8{
        "+--+", //
        "+--+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(1, count);
}

test "rectangle of width 1 is counted" {
    const strings = [_][]const u8{
        "++", //
        "||", //
        "++", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(1, count);
}

test "1x1 square is counted" {
    const strings = [_][]const u8{
        "++", //
        "++", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(1, count);
}

test "only complete rectangles are counted" {
    const strings = [_][]const u8{
        "  +-+", //
        "    |", //
        "+-+-+", //
        "| | -", //
        "+-+-+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(1, count);
}

test "rectangles can be of different sizes" {
    const strings = [_][]const u8{
        "+------+----+", //
        "|      |    |", //
        "+---+--+    |", //
        "|   |       |", //
        "+---+-------+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(3, count);
}

test "corner is required for a rectangle to be complete" {
    const strings = [_][]const u8{
        "+------+----+", //
        "|      |    |", //
        "+------+    |", //
        "|   |       |", //
        "+---+-------+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(2, count);
}

test "large input with many rectangles" {
    const strings = [_][]const u8{
        "+---+--+----+", //
        "|   +--+----+", //
        "+---+--+    |", //
        "|   +--+----+", //
        "+---+--+--+-+", //
        "+---+--+--+-+", //
        "+------+  | |", //
        "          +-+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(60, count);
}

test "rectangles must have four sides" {
    const strings = [_][]const u8{
        "+-+ +-+", //
        "| | | |", //
        "+-+-+-+", //
        "  | |  ", //
        "+-+-+-+", //
        "| | | |", //
        "+-+ +-+", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(5, count);
}

test "very large input" {
    const strings = [_][]const u8{
        "      +-----+--------+    +-----+ ", //
        "++---++-----+--------+---++-----++", //
        "||+--++-----+-+-++   |   ||     ||", //
        "|||  ||     +-+-++-+ |   ||     ||", //
        "|||  ||     | | || | |   ||     ||", //
        "||| +++-----+-+-++-+-+---++-+   ||", //
        "||| |||     | | || | |+--++-+-+ ||", //
        "||| +++---+-+-+-++-+-++--++-+ | ||", //
        "||| |||+--+-+-+-+| | |+--++---+ ||", //
        "||| ||||  | | | || | |+-+||     ||", //
        "||+-++++--+-+++-++-+-++-+++---++||", //
        "||  |+++--+-+++-+--+-+| |||   ||||", //
        "+++-+++++---++--+-++-++-+++---+|||", //
        " |+-+++++---++--+ || || |||   ||||", //
        " |  +++++---++--+-++-++-++++  ||||", //
        " |   ||||   |+----++-++-++++--+++|", //
        " |   |+++---+|    || || ||    || |", //
        "+++  |||+---++----+| || ||    || |", //
        "|||  +++----++----++-++-++----++-+", //
        "+++---++----++-----+-++-++----++  ", //
        "                      +-+         ", //
    };
    const count = rectangles.rectangles(&strings);
    try testing.expectEqual(2063, count);
}

```

```zig
/// Returns the number of rectangles in the ASCII diagram `strings`.
pub fn rectangles(strings: []const []const u8) usize {
    const rows = strings.len;
    if (rows == 0) return 0;
    const cols = strings[0].len;
    if (cols == 0) return 0;

    var count: usize = 0;

    // Find all '+' positions
    var plus_positions: []std.ArrayList(struct { row: usize, col: usize }) = undefined;
    // We'll just iterate through all possible corner pairs

    for (0..rows) |r1| {
        for (0..cols) |c1| {
            if (strings[r1][c1] != '+') continue;
            // c1 is top-left corner column
            for (c1 + 1..cols) |c2| {
                if (strings[r1][c2] != '+') continue;
                // Check top edge from c1 to c2
                var top_ok = true;
                for (c1 + 1..c2) |c| {
                    const ch = strings[r1][c];
                    if (ch != '-' && ch != '+') {
                        top_ok = false;
                        break;
                    }
                }
                if (!top_ok) continue;

                // c2 is top-right corner column, now look for bottom corners
                for (r1 + 1..rows) |r2| {
                    if (strings[r2][c1] != '+') continue;
                    if (strings[r2][c2] != '+') continue;

                    // Check bottom edge
                    var bottom_ok = true;
                    for (c1 + 1..c2) |c| {
                        const ch = strings[r2][c];
                        if (ch != '-' && ch != '+') {
                            bottom_ok = false;
                            break;
                        }
                    }
                    if (!bottom_ok) continue;

                    // Check left edge
                    var left_ok = true;
                    for (r1 + 1..r2) |r| {
                        const ch = strings[r][c1];
                        if (ch != '|' && ch != '+') {
                            left_ok = false;
                            break;
                        }
                    }
                    if (!left_ok) continue;

                    // Check right edge
                    var right_ok = true;
                    for (r1 + 1..r2) |r| {
                        const ch = strings[r][c2];
                        if (ch != '|' && ch != '+') {
                            right_ok = false;
                            break;
                        }
                    }
                    if (!right_ok) continue;

                    count += 1;
                }
            }
        }
    }

    return count;
}

